export type PlatformIconId = (typeof platformIconIds)[number];

export const platformRegistryById: Readonly<Record<PlatformIconId, PlatformIconDefinition>> =
  Object.freeze(
    Object.fromEntries(platformRegistry.map((platform) => [platform.id, platform])) as unknown as Record<
      PlatformIconId,
      PlatformIconDefinition
    >,
  );

export function getPlatformIcon(id: PlatformIconId): PlatformIconDefinition {
  return platformRegistryById[id];
}
